def process(wollastonTidy, ejOver90) -> pd.DataFrame:
    import pandas as pd

    # Wollaston Beach is in Quincy
    is_ej = (ejOver90['Municipality'].str.lower() == 'quincy').any()
    if not is_ej:
        return pd.DataFrame([{'correlation': None, 'note': 'Quincy not >90% EJ in EJ dataset; no qualifying Wollaston data.'}])

    df = wollastonTidy.copy()

    # Pearson correlation between 3-day rain and Enterococcus
    corr = df['rain3'].corr(df['enterococcus'], method='pearson')
    return pd.DataFrame([{'correlation': corr, 'n': len(df)}])

def process(wollastonTidy, ejOver90) -> pd.DataFrame:
    import pandas as pd

    # Wollaston Beach is in Quincy
    is_ej = (ejOver90['Municipality'].astype(str).str.strip().str.lower() == 'quincy').any()
    if not is_ej:
        return pd.DataFrame([{'correlation': None, 'n': 0, 'note': 'Quincy not >90% EJ in EJ dataset; no qualifying Boston Harbor beach data from Wollaston sheet.'}])

    df = wollastonTidy.copy()
    if not set(['rain3', 'enterococcus']).issubset(df.columns):
        return pd.DataFrame([{'correlation': None, 'n': 0, 'note': 'wollastonTidy missing expected columns', 'columns': '|'.join(df.columns)}])

    corr = df['rain3'].corr(df['enterococcus'], method='pearson')
    return pd.DataFrame([{'correlation': corr, 'n': int(len(df))}])
